package com.barrowswithbenefits;

enum BarrowsBrotherLocationData
{
    // Surface dig rectangles are the complete diggable mound areas.
    // Coordinates are region-local south-west corners in Barrows region 14131.
    DHAROK("Dharok", 20720, 36, 52, 52, 31, 6, 6),
    AHRIM("Ahrim", 20770, 36, 37, 42, 22, 6, 7),
    VERAC("Verac", 20772, 55, 42, 35, 31, 5, 6),
    TORAG("Torag", 20721, 49, 20, 32, 17, 5, 4),
    KARIL("Karil", 20771, 29, 20, 43, 9, 7, 7),
    GUTHAN("Guthan", 20722, 17, 40, 54, 16, 7, 5);

    private final String displayName;
    private final int sarcophagusObjectId;
    private final int cryptRegionX;
    private final int cryptRegionY;
    private final int surfaceRegionX;
    private final int surfaceRegionY;
    private final int surfaceDigWidth;
    private final int surfaceDigHeight;

    BarrowsBrotherLocationData(
        String displayName,
        int sarcophagusObjectId,
        int cryptRegionX,
        int cryptRegionY,
        int surfaceRegionX,
        int surfaceRegionY,
        int surfaceDigWidth,
        int surfaceDigHeight)
    {
        this.displayName = displayName;
        this.sarcophagusObjectId = sarcophagusObjectId;
        this.cryptRegionX = cryptRegionX;
        this.cryptRegionY = cryptRegionY;
        this.surfaceRegionX = surfaceRegionX;
        this.surfaceRegionY = surfaceRegionY;
        this.surfaceDigWidth = surfaceDigWidth;
        this.surfaceDigHeight = surfaceDigHeight;
    }

    String getDisplayName()
    {
        return displayName;
    }

    int getSarcophagusObjectId()
    {
        return sarcophagusObjectId;
    }

    int getCryptRegionX()
    {
        return cryptRegionX;
    }

    int getCryptRegionY()
    {
        return cryptRegionY;
    }

    int getSurfaceRegionX()
    {
        return surfaceRegionX;
    }

    int getSurfaceRegionY()
    {
        return surfaceRegionY;
    }


    int getSurfaceDigWidth()
    {
        return surfaceDigWidth;
    }

    int getSurfaceDigHeight()
    {
        return surfaceDigHeight;
    }

    boolean matchesNpcName(String npcName)
    {
        return npcName != null
            && (npcName.equals(displayName) || npcName.startsWith(displayName + " "));
    }

    static BarrowsBrotherLocationData fromSarcophagusObjectId(int objectId)
    {
        for (BarrowsBrotherLocationData brother : values())
        {
            if (brother.sarcophagusObjectId == objectId)
            {
                return brother;
            }
        }

        return null;
    }
}

/*
 * Barrows door tracking/highlighting logic adapted from
 * Barrows-Door-Highlighter by Jordan Hans (2022), BSD-2-Clause.
 * See THIRD_PARTY_NOTICES.txt included with this project.
 */
package com.barrowswithbenefits;

import java.awt.Font;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import net.runelite.api.Perspective;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.Stroke;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.ObjectComposition;
import net.runelite.api.WallObject;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;
import net.runelite.client.ui.overlay.OverlayUtil;

final class BarrowsHelperOverlay extends Overlay
{
    private final Client client;
    private final BarrowsWithBenefitsPlugin plugin;
    private final BarrowsWithBenefitsConfig config;
    private final ModelOutlineRenderer modelOutlineRenderer;

    @Inject
    BarrowsHelperOverlay(Client client, BarrowsWithBenefitsPlugin plugin, BarrowsWithBenefitsConfig config, ModelOutlineRenderer modelOutlineRenderer)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        this.modelOutlineRenderer = modelOutlineRenderer;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.UNDER_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        graphics.setFont(new Font("SansSerif", Font.PLAIN, 12));
        renderTargetNpcOutlines();
        // Match the known-working Barrows Door Highlighter: tunnel doors are
        // rendered on top-level WorldView plane 0. Do not use WorldPoint plane
        // here; that was preventing valid Barrows doors from rendering.
        if ((config.highlightTunnelDoors() || config.showShortestRouteLine())
                && client.getTopLevelWorldView() != null
                && client.getTopLevelWorldView().getPlane() == 0)
        {
            renderUsableDoors(graphics);
        }

        if (config.showPuzzleAnswer())
        {
            renderPuzzleAnswer(graphics);
        }

        return null;
    }

    private static final int CENTRE_ROOM = 4;

    /**
     * Barrows tunnels form a 3x3 room grid. Rather than comparing a door's raw
     * coordinate with the chest, build the graph from the doors which are
     * actually usable in this run and BFS back from the centre room.
     */
    private void renderUsableDoors(Graphics2D graphics)
    {
        if (client.getLocalPlayer() == null || !plugin.isInTunnelMaze())
        {
            return;
        }

        WorldPoint player = client.getLocalPlayer().getWorldLocation();
        if (player == null)
        {
            return;
        }

        /*
         * The old implementation tried to infer a 3x3 room graph from door
         * coordinates. That is too brittle for Barrows because each corridor has
         * multiple physical door leaves/ends. Instead pathfind on RuneLite's live
         * collision map. WorldArea.canTravelInDirection uses the same collision
         * flags the client uses for movement, so the blue route cannot cut through
         * walls or across the middle of rooms.
         */
        List<WorldPoint> path = findShortestWalkablePath(player);
        if (path.isEmpty())
        {
            // Door highlighting must never disappear just because the optional
            // shortest-path solver cannot resolve a route on this tick.
            if (config.highlightTunnelDoors())
            {
                renderAllUsableDoors(graphics);
            }
            return;
        }

        if (config.showShortestRouteLine())
        {
            renderPathTiles(graphics, path);
        }

        if (config.highlightTunnelDoors())
        {
            if (config.shortestRouteDoorsOnly())
            {
                renderPathDoors(graphics, path);
            }
            else
            {
                renderAllUsableDoors(graphics);
            }
        }
    }

    private List<WorldPoint> findShortestWalkablePath(WorldPoint start)
    {
        net.runelite.api.WorldView worldView = client.getTopLevelWorldView();
        if (worldView == null || worldView.getCollisionMaps() == null)
        {
            return java.util.Collections.emptyList();
        }

        /*
         * Build explicit bidirectional edges through each currently usable Barrows
         * wall door. A closed wall-door is represented as blocked in the collision
         * map even when its "Open" action makes it traversable, which is why the
         * previous pure-collision BFS found no route.
         */
        Map<WorldPoint, Set<WorldPoint>> doorCrossings = new HashMap<>();
        for (WallObject door : plugin.getBarrowsDoors())
        {
            if (door == null || door.getWorldLocation() == null || !isUsableDoor(door))
            {
                continue;
            }

            WorldPoint p = door.getWorldLocation();
            int dx = 0;
            int dy = 0;
            switch (door.getOrientationA())
            {
                case 1:
                    dx = -1;
                    break;
                case 4:
                    dx = 1;
                    break;
                case 8:
                    dy = -1;
                    break;
                default:
                    dy = 1;
                    break;
            }

            WorldPoint q = new WorldPoint(p.getX() + dx, p.getY() + dy, p.getPlane());
            doorCrossings.computeIfAbsent(p, k -> new HashSet<>()).add(q);
            doorCrossings.computeIfAbsent(q, k -> new HashSet<>()).add(p);
        }

        Queue<WorldPoint> queue = new ArrayDeque<>();
        Map<WorldPoint, WorldPoint> previous = new HashMap<>();
        Set<WorldPoint> visited = new HashSet<>();
        queue.add(start);
        visited.add(start);

        // Cardinal movement produces a clean RuneScape-style route and prevents
        // corner-cutting/diagonal blue tiles.
        final int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        WorldPoint goal = null;
        int examined = 0;
        final int MAX_TILES = 12000;

        while (!queue.isEmpty() && examined++ < MAX_TILES)
        {
            WorldPoint current = queue.remove();
            if (isCentreRoomTile(current))
            {
                goal = current;
                break;
            }

            WorldArea area = new WorldArea(current, 1, 1);
            for (int[] d : dirs)
            {
                WorldPoint next = new WorldPoint(
                    current.getX() + d[0],
                    current.getY() + d[1],
                    current.getPlane());

                boolean normalMove = area.canTravelInDirection(worldView, d[0], d[1]);
                boolean usableDoorCrossing = doorCrossings
                    .getOrDefault(current, java.util.Collections.emptySet())
                    .contains(next);

                if ((!normalMove && !usableDoorCrossing) || visited.contains(next))
                {
                    continue;
                }

                // LocalPoint being present is a safer scene-boundary test than a
                // hard-coded region id and also works across instanced WorldViews.
                if (LocalPoint.fromWorld(worldView, next) == null)
                {
                    continue;
                }

                visited.add(next);
                previous.put(next, current);
                queue.add(next);
            }
        }

        if (goal == null)
        {
            return java.util.Collections.emptyList();
        }

        List<WorldPoint> path = new ArrayList<>();
        for (WorldPoint p = goal; p != null; p = previous.get(p))
        {
            path.add(p);
            if (p.equals(start))
            {
                break;
            }
        }
        java.util.Collections.reverse(path);
        return path;
    }

    private static boolean isCentreRoomTile(WorldPoint p)
    {
        return p.getX() >= 3546 && p.getX() <= 3557
            && p.getY() >= 9689 && p.getY() <= 9700;
    }

    private void renderPathTiles(Graphics2D graphics, List<WorldPoint> path)
    {
        if (path.size() < 2)
        {
            return;
        }

        // Route progress is automatic: BFS starts from the player's current tile
        // every render, so travelled tiles disappear from the line immediately.
        Stroke oldStroke = graphics.getStroke();
        Color oldColor = graphics.getColor();
        Font oldFont = graphics.getFont();
        graphics.setStroke(new BasicStroke(
            config.shortestRouteLineWidth(),
            BasicStroke.CAP_ROUND,
            BasicStroke.JOIN_ROUND));
        graphics.setColor(config.shortestRouteLineColor());

        java.awt.Point previous = null;
        java.awt.Point lastVisible = null;
        int lastVisibleIndex = -1;

        for (int i = 1; i < path.size(); i++)
        {
            LocalPoint lp = LocalPoint.fromWorld(client.getTopLevelWorldView(), path.get(i));
            if (lp == null)
            {
                continue;
            }

            net.runelite.api.Point canvas = Perspective.localToCanvas(client, lp, 0);
            if (canvas == null)
            {
                continue;
            }

            java.awt.Point current = new java.awt.Point(canvas.getX(), canvas.getY());
            if (previous != null)
            {
                graphics.drawLine(previous.x, previous.y, current.x, current.y);
            }
            previous = current;
            lastVisible = current;
            lastVisibleIndex = i;
        }

        // If some of the route remains beyond what can currently be projected,
        // put a compact arrow at the end of the visible line.
        if (config.showChestDirectionIndicator()
            && lastVisible != null
            && lastVisibleIndex >= 0
            && lastVisibleIndex < path.size() - 1)
        {
            WorldPoint from = path.get(lastVisibleIndex);
            WorldPoint to = path.get(Math.min(path.size() - 1, lastVisibleIndex + 1));
            int dx = Integer.compare(to.getX(), from.getX());
            int dy = Integer.compare(to.getY(), from.getY());

            String arrow;
            if (Math.abs(dx) > Math.abs(dy))
            {
                arrow = dx >= 0 ? ">" : "<";
            }
            else
            {
                arrow = dy >= 0 ? "^" : "v";
            }

            graphics.setFont(new Font("SansSerif", Font.BOLD, 16));
            graphics.drawString(arrow, lastVisible.x - 4, lastVisible.y + 5);
        }

        graphics.setStroke(oldStroke);
        graphics.setColor(oldColor);
        graphics.setFont(oldFont);
    }

    private void renderPathDoors(Graphics2D graphics, List<WorldPoint> path)
    {
        if (path.size() < 2)
        {
            return;
        }

        net.runelite.api.WorldView worldView = client.getTopLevelWorldView();
        List<WallObject> routeDoors = new ArrayList<>();

        for (int i = 0; i < path.size() - 1; i++)
        {
            WorldPoint from = path.get(i);
            WorldPoint to = path.get(i + 1);
            int dx = to.getX() - from.getX();
            int dy = to.getY() - from.getY();

            WorldArea area = new WorldArea(from, 1, 1);
            if (area.canTravelInDirection(worldView, dx, dy))
            {
                continue;
            }

            for (WallObject door : plugin.getBarrowsDoors())
            {
                if (door == null || door.getWorldLocation() == null || !isUsableDoor(door))
                {
                    continue;
                }

                WorldPoint p = door.getWorldLocation();
                int ox = 0, oy = 0;
                switch (door.getOrientationA())
                {
                    case 1: ox = -1; break;
                    case 4: ox = 1; break;
                    case 8: oy = -1; break;
                    default: oy = 1; break;
                }
                WorldPoint q = new WorldPoint(p.getX() + ox, p.getY() + oy, p.getPlane());

                if ((from.equals(p) && to.equals(q)) || (from.equals(q) && to.equals(p)))
                {
                    if (!routeDoors.contains(door))
                    {
                        routeDoors.add(door);
                    }
                }
            }
        }

        if (routeDoors.isEmpty())
        {
            return;
        }

        // Add only the adjacent second leaf of each selected doorway.
        List<WallObject> expanded = new ArrayList<>(routeDoors);
        for (WallObject chosen : new ArrayList<>(routeDoors))
        {
            WorldPoint p = chosen.getWorldLocation();
            for (WallObject candidate : plugin.getBarrowsDoors())
            {
                if (candidate == null || candidate.getWorldLocation() == null || !isUsableDoor(candidate))
                {
                    continue;
                }
                WorldPoint q = candidate.getWorldLocation();
                if (q.getPlane() == p.getPlane()
                    && Math.abs(q.getX() - p.getX()) + Math.abs(q.getY() - p.getY()) <= 1
                    && !expanded.contains(candidate))
                {
                    expanded.add(candidate);
                }
            }
        }

        WallObject nextDoor = routeDoors.get(0);
        WorldPoint nextPoint = nextDoor.getWorldLocation();

        Stroke oldStroke = graphics.getStroke();
        Color oldColor = graphics.getColor();

        for (WallObject door : expanded)
        {
            Shape hull = door.getConvexHull();
            if (hull == null)
            {
                continue;
            }

            boolean isNext = config.emphasizeNextDoor()
                && door.getWorldLocation() != null
                && nextPoint != null
                && Math.abs(door.getWorldLocation().getX() - nextPoint.getX())
                 + Math.abs(door.getWorldLocation().getY() - nextPoint.getY()) <= 1;

            Color base = config.tunnelDoorColor();
            Color color = isNext
                ? new Color(base.getRed(), base.getGreen(), base.getBlue(), Math.max(base.getAlpha(), 220))
                : new Color(base.getRed(), base.getGreen(), base.getBlue(), Math.min(base.getAlpha(), 90));

            graphics.setStroke(new BasicStroke(
                isNext ? Math.min(10, config.tunnelDoorWidth() + 2) : config.tunnelDoorWidth()));
            OverlayUtil.renderPolygon(graphics, hull, color);
        }

        graphics.setStroke(oldStroke);
        graphics.setColor(oldColor);
    }

    private void renderAllUsableDoors(Graphics2D graphics)
    {
        Stroke oldStroke = graphics.getStroke();
        Color oldColor = graphics.getColor();
        graphics.setStroke(new BasicStroke(config.tunnelDoorWidth()));
        for (WallObject door : plugin.getBarrowsDoors())
        {
            if (door != null && isUsableDoor(door))
            {
                Shape hull = door.getConvexHull();
                if (hull != null)
                {
                    OverlayUtil.renderPolygon(graphics, hull, config.tunnelDoorColor());
                }
            }
        }
        graphics.setStroke(oldStroke);
        graphics.setColor(oldColor);
    }

    private int[] bfsDistances(Map<Integer, Set<Integer>> graph, int start)
    {
        int[] distances = new int[9];
        Arrays.fill(distances, Integer.MAX_VALUE);
        distances[start] = 0;

        Queue<Integer> queue = new ArrayDeque<>();
        queue.add(start);

        while (!queue.isEmpty())
        {
            int room = queue.remove();
            for (int next : graph.getOrDefault(room, java.util.Collections.emptySet()))
            {
                if (distances[next] == Integer.MAX_VALUE)
                {
                    distances[next] = distances[room] + 1;
                    queue.add(next);
                }
            }
        }
        return distances;
    }

    /**
     * Convert a world point into the Barrows 3x3 room grid:
     * 0 1 2
     * 3 4 5
     * 6 7 8
     *
     * The centre room occupies x=3546..3557, y=9689..9700. The same boundary
     * lines divide the surrounding eight tunnel rooms.
     */
    private static WorldPoint roomCentre(int room, int plane)
    {
        // Centres of the nine Barrows tunnel rooms:
        // 0 1 2
        // 3 4 5
        // 6 7 8
        final int[] xs = {3539, 3551, 3564};
        final int[] ys = {9707, 9694, 9682};

        if (room < 0 || room >= 9)
        {
            return null;
        }

        int row = room / 3;
        int col = room % 3;
        return new WorldPoint(xs[col], ys[row], plane);
    }

    private static int roomFor(WorldPoint point)
    {
        // Use nearest known tunnel-room centre. This is stable for doors positioned
        // several tiles inside a corridor, unlike the old hard boundary sampling.
        final int[] xs = {3539, 3551, 3564};
        final int[] ys = {9707, 9694, 9682};
        int bestRoom = 0;
        int bestDistance = Integer.MAX_VALUE;
        for (int row = 0; row < 3; row++)
        {
            for (int col = 0; col < 3; col++)
            {
                int d = Math.abs(point.getX() - xs[col]) + Math.abs(point.getY() - ys[row]);
                if (d < bestDistance)
                {
                    bestDistance = d;
                    bestRoom = row * 3 + col;
                }
            }
        }
        return bestRoom;
    }

    /**
     * Determine which two adjacent grid rooms a door joins by sampling a tile
     * on each side of it. This avoids hard-coding individual door IDs and also
     * groups the two adjacent wall objects which make up one visual doorway.
     */
    private static DoorEdge edgeFor(WallObject door)
    {
        WorldPoint p = door.getWorldLocation();
        if (p == null)
        {
            return null;
        }

        // Find the closest adjacent room pair to this live Barrows door. This
        // handles both physical ends of the short connecting corridors.
        int bestA = -1;
        int bestB = -1;
        int best = Integer.MAX_VALUE;
        for (int a = 0; a < 9; a++)
        {
            for (int b = a + 1; b < 9; b++)
            {
                if (!adjacent(a, b))
                {
                    continue;
                }
                WorldPoint ca = roomCentre(a, p.getPlane());
                WorldPoint cb = roomCentre(b, p.getPlane());
                int midX = (ca.getX() + cb.getX()) / 2;
                int midY = (ca.getY() + cb.getY()) / 2;
                int d = Math.abs(p.getX() - midX) + Math.abs(p.getY() - midY);
                if (d < best)
                {
                    best = d;
                    bestA = a;
                    bestB = b;
                }
            }
        }
        return bestA < 0 ? null : new DoorEdge(door, bestA, bestB);
    }

    private static boolean adjacent(int a, int b)
    {
        int ar = a / 3;
        int ac = a % 3;
        int br = b / 3;
        int bc = b % 3;
        return Math.abs(ar - br) + Math.abs(ac - bc) == 1;
    }

    private static final class Doorway
    {
        private final int a;
        private final int b;
        private final List<WallObject> doors = new ArrayList<>();
        private boolean usable;

        private Doorway(int a, int b)
        {
            this.a = a;
            this.b = b;
        }

        private boolean touches(int room)
        {
            return a == room || b == room;
        }

        private int other(int room)
        {
            if (a == room)
            {
                return b;
            }
            if (b == room)
            {
                return a;
            }
            return -1;
        }
    }

    private static final class DoorEdge
    {
        private final WallObject door;
        private final int a;
        private final int b;

        private DoorEdge(WallObject door, int a, int b)
        {
            this.door = door;
            this.a = a;
            this.b = b;
        }

        private boolean touches(int room)
        {
            return a == room || b == room;
        }

        private int other(int room)
        {
            if (a == room)
            {
                return b;
            }
            if (b == room)
            {
                return a;
            }
            return -1;
        }
    }

    private boolean isUsableDoor(WallObject door)
    {
        ObjectComposition composition = client.getObjectDefinition(door.getId());
        if (composition == null || composition.getImpostorIds() == null)
        {
            return false;
        }

        ObjectComposition impostor = composition.getImpostor();
        if (impostor == null)
        {
            return false;
        }

        String[] actions = impostor.getActions();
        return actions != null && actions.length > 0;
    }

    private void renderTargetNpcOutlines()
    {
        if (!config.highlightTunnelTargetNpcs()
                || !plugin.isInTunnelMaze()
                || plugin.areTunnelKillTargetsComplete())
        {
            // Once every configured tunnel kill target has been reached, remove
            // all NPC outlines for the rest of this run. The plugin's existing
            // chest/run reset clears the kill counters, so they return next run.
            return;
        }

        for (NPC npc : client.getNpcs())
        {
            if (npc != null && plugin.isTunnelTargetStillNeeded(npc.getName()))
            {
                modelOutlineRenderer.drawOutline(
                        npc,
                        config.tunnelNpcHighlightWidth(),
                        config.tunnelNpcHighlightColor(),
                        2);
            }
        }
    }

    private void renderPuzzleAnswer(Graphics2D graphics)
    {
        Widget answerWidget = plugin.getPuzzleAnswer();
        if (answerWidget == null || answerWidget.isHidden() || answerWidget.getBounds() == null)
        {
            return;
        }

        Rectangle bounds = answerWidget.getBounds();

        // User-requested marker: solid, opaque fill (no outline) over the correct
        // answer, using the configurable puzzle answer colour.
        graphics.setColor(config.puzzleAnswerColor());
        graphics.fillRect(bounds.x, bounds.y, bounds.width, bounds.height);
    }

}

package com.barrowswithbenefits;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/** Draws compact brother initials at the six Barrows mounds on the minimap. */
final class BarrowsMinimapOverlay extends Overlay
{
    private static final int ABOVE_GROUND_REGION_ID = 14131;
    private static final int REGION_BASE_X = 3520;
    private static final int REGION_BASE_Y = 3264;
    private static final Font LETTER_FONT = new Font("Arial", Font.BOLD, 12);

    private final Client client;
    private final BarrowsWithBenefitsPlugin plugin;
    private final BarrowsWithBenefitsConfig config;

    @Inject
    BarrowsMinimapOverlay(Client client, BarrowsWithBenefitsPlugin plugin, BarrowsWithBenefitsConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (client.getLocalPlayer() == null
            || client.getLocalPlayer().getWorldLocation().getRegionID() != ABOVE_GROUND_REGION_ID)
        {
            return null;
        }

        graphics.setFont(LETTER_FONT);
        FontMetrics fm = graphics.getFontMetrics();

        for (BarrowsBrotherLocationData brother : BarrowsBrotherLocationData.values())
        {
            // Use the exact same surface rectangle data as the large mound overlay.
            int centreX = REGION_BASE_X + brother.getSurfaceRegionX()
                + (brother.getSurfaceDigWidth() - 1) / 2;
            int centreY = REGION_BASE_Y + brother.getSurfaceRegionY()
                + (brother.getSurfaceDigHeight() - 1) / 2;

            LocalPoint local = LocalPoint.fromWorld(client, new WorldPoint(centreX, centreY, 0));
            if (local == null)
            {
                continue;
            }

            Point point = Perspective.localToMinimap(client, local);
            if (point == null)
            {
                continue; // RuneLite clips locations outside the usable minimap radius.
            }

            String letter = brother.getDisplayName().substring(0, 1).toUpperCase();
            Color color;
            if (brother == plugin.getTunnelBrother())
            {
                color = config.tunnelHighlightColor();
            }
            else if (plugin.isBrotherKilled(brother))
            {
                color = config.killedBrotherColor();
            }
            else
            {
                color = config.unkilledBrotherColor();
            }

            Point textPoint = new Point(
                point.getX() - fm.stringWidth(letter) / 2,
                point.getY() + fm.getAscent() / 2);
            OverlayUtil.renderTextLocation(graphics, textPoint, letter, color);
        }

        return null;
    }
}

package com.barrowswithbenefits;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.geom.Area;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.WallObject;
import net.runelite.api.GroundObject;
import net.runelite.api.DecorativeObject;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Draws the six labelled brother tiles both above ground (the mounds you dig into) and
 * below ground (the crypt rooms containing each sarcophagus), colouring each tile red or
 * green depending on whether that brother has been killed yet this run, and outlining
 * whichever brother's room is known to lead down to the crypt maze and chest in blue.
 *
 * The tile colours are always read live from the plugin's current state, so they update
 * immediately whenever a brother dies, whenever the tunnel brother becomes known, and
 * whenever the player walks back into view of a tile (on the surface, going back down, or
 * coming back up) - there is no separate "refresh" step required.
 */
final class BarrowsOverlay extends Overlay
{
    private static final int ABOVE_GROUND_REGION_ID = 14131;
    private static final int CRYPT_REGION_ID = 14231;
    private static final int CRYPT_PLANE = 3;
    private static final Stroke TILE_STROKE = new BasicStroke(2.0f);
    private static final Stroke OBJECT_STROKE = new BasicStroke(3.0f);

    private final Client client;
    private final BarrowsWithBenefitsPlugin plugin;
    private final BarrowsWithBenefitsConfig config;

    @Inject
    BarrowsOverlay(
        Client client,
        BarrowsWithBenefitsPlugin plugin,
        BarrowsWithBenefitsConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        graphics.setFont(new Font("SansSerif", Font.BOLD, 12));
        if (client.getLocalPlayer() == null)
        {
            return null;
        }

        int regionId = client.getLocalPlayer().getWorldLocation().getRegionID();
        BarrowsBrotherLocationData tunnelBrother = plugin.getTunnelBrother();

        if (regionId == ABOVE_GROUND_REGION_ID)
        {
            if (config.showSurfaceBrotherTiles())
            {
                renderSurfaceDigAreas(graphics, regionId, tunnelBrother);
            }
            return null;
        }

        if (regionId != CRYPT_REGION_ID
            || client.getLocalPlayer().getWorldLocation().getPlane() != CRYPT_PLANE)
        {
            return null;
        }

        // Inside the brother crypts we deliberately do NOT draw floor tiles.
        // Instead, labels/status are rendered directly over the sarcophagi.
        if (config.showCryptBrotherTiles())
        {
            renderSarcophagusHulls(graphics);
        }

        // The staircase renderer is kill-gated internally: it draws nothing
        // before/during the fight and only shows the green exit after the kill.
        renderCurrentRoomStaircase(graphics);

        return null;
    }

    /**
     * Draw every diggable tile on each surface mound.
     *
     * Dharok: 6x6 (36 tiles)
     * Verac:   5x6 (30 tiles)
     * Ahrim:   6x7 (42 tiles)
     * Guthan:  7x5 (35 tiles)
     * Torag:   5x4 (20 tiles)
     * Karil:   7x7 (49 tiles)
     *
     * The brother name is drawn once at the visual centre of the rectangle.
     */
    private void renderSurfaceDigAreas(
        Graphics2D graphics,
        int regionId,
        BarrowsBrotherLocationData tunnelBrother)
    {
        WorldView worldView = client.getLocalPlayer().getWorldView();
        int plane = worldView.getPlane();

        for (BarrowsBrotherLocationData brother : BarrowsBrotherLocationData.values())
        {
            boolean isTunnel = config.showTunnelSarcophagus() && brother == tunnelBrother;
            boolean killed = plugin.isBrotherKilled(brother);

            Color markerColor;
            if (isTunnel)
            {
                markerColor = config.tunnelHighlightColor();
            }
            else if (config.showKillStatusColors() && killed)
            {
                markerColor = config.killedBrotherColor();
            }
            else
            {
                markerColor = config.unkilledBrotherColor();
            }

            // Extremely faint mound area. Keep the brother name readable, but make
            // the large world-space rectangle only lightly visible.
            Color areaFillColor = new Color(
                markerColor.getRed(),
                markerColor.getGreen(),
                markerColor.getBlue(),
                18);
            Color areaOutlineColor = new Color(
                markerColor.getRed(),
                markerColor.getGreen(),
                markerColor.getBlue(),
                38);

            // Merge every projected diggable tile into ONE Area. This removes the
            // individual tile grid and leaves a single large mound shape/border.
            Area moundArea = new Area();

            for (int dx = 0; dx < brother.getSurfaceDigWidth(); dx++)
            {
                for (int dy = 0; dy < brother.getSurfaceDigHeight(); dy++)
                {
                    WorldPoint tilePoint = WorldPoint.fromRegion(
                        regionId,
                        brother.getSurfaceRegionX() + dx,
                        brother.getSurfaceRegionY() + dy,
                        plane);
                    LocalPoint localPoint = LocalPoint.fromWorld(worldView, tilePoint);
                    if (localPoint == null)
                    {
                        continue;
                    }

                    Polygon polygon = Perspective.getCanvasTilePoly(client, localPoint);
                    if (polygon != null)
                    {
                        moundArea.add(new Area(polygon));
                    }
                }
            }

            Stroke previousStroke = graphics.getStroke();
            Color previousColor = graphics.getColor();
            Font previousFont = graphics.getFont();

            if (!moundArea.isEmpty())
            {
                graphics.setColor(areaFillColor);
                graphics.fill(moundArea);

                graphics.setStroke(TILE_STROKE);
                graphics.setColor(areaOutlineColor);
                graphics.draw(moundArea);
            }

            // Draw the brother name once in the centre of the whole diggable area.
            double centerX = brother.getSurfaceRegionX() + (brother.getSurfaceDigWidth() - 1) / 2.0;
            double centerY = brother.getSurfaceRegionY() + (brother.getSurfaceDigHeight() - 1) / 2.0;
            int labelRegionX = (int) Math.round(centerX);
            int labelRegionY = (int) Math.round(centerY);

            WorldPoint labelPoint = WorldPoint.fromRegion(
                regionId, labelRegionX, labelRegionY, plane);
            LocalPoint labelLocal = LocalPoint.fromWorld(worldView, labelPoint);

            if (labelLocal != null)
            {
                String label = brother.getDisplayName();
                graphics.setFont(FontManager.getRunescapeBoldFont());
                Point textLocation = Perspective.getCanvasTextLocation(
                    client, graphics, labelLocal, label, 0);

                if (textLocation != null)
                {
                    OverlayUtil.renderTextLocation(
                        graphics, textLocation, label, markerColor);
                }
            }

            graphics.setStroke(previousStroke);
            graphics.setColor(previousColor);
            graphics.setFont(previousFont);
        }
    }

    /**
     * Outlines each brother's crypt sarcophagus with their kill-status colour (red/green),
     * and additionally with the blue tunnel colour if they are the known tunnel brother.
     */
    private void renderSarcophagusHulls(Graphics2D graphics)
    {
        WorldView worldView = client.getLocalPlayer().getWorldView();
        int plane = worldView.getPlane();
        WorldPoint player = client.getLocalPlayer().getWorldLocation();
        BarrowsBrotherLocationData tunnelBrother = plugin.getTunnelBrother();

        // Only mark the actual sarcophagus object in the crypt room the player is
        // currently standing in. Do not paint the floor tile beneath it.
        BarrowsBrotherLocationData currentBrother = nearestCryptBrother(player, plane, 12);
        if (currentBrother == null)
        {
            return;
        }

        boolean killed = plugin.isBrotherKilled(currentBrother);
        boolean isTunnel = currentBrother == tunnelBrother;
        Color markerColor = isTunnel
            ? config.tunnelHighlightColor()
            : (config.showKillStatusColors()
                ? (killed ? config.killedBrotherColor() : config.unkilledBrotherColor())
                : config.unkilledBrotherColor());

        WorldPoint markerPoint = WorldPoint.fromRegion(
            CRYPT_REGION_ID,
            currentBrother.getCryptRegionX(),
            currentBrother.getCryptRegionY(),
            plane);
        LocalPoint markerLocalPoint = LocalPoint.fromWorld(worldView, markerPoint);
        if (markerLocalPoint == null)
        {
            return;
        }

        Tile[][][] tiles = worldView.getScene().getTiles();
        int minX = Math.max(0, markerLocalPoint.getSceneX() - 7);
        int maxX = Math.min(tiles[plane].length - 1, markerLocalPoint.getSceneX() + 7);
        int minY = Math.max(0, markerLocalPoint.getSceneY() - 7);
        int maxY = Math.min(tiles[plane][0].length - 1, markerLocalPoint.getSceneY() + 7);

        Stroke oldStroke = graphics.getStroke();
        Color oldColor = graphics.getColor();
        Font oldFont = graphics.getFont();

        // Keep the sarcophagus object outline deliberately light/subtle while
        // retaining the configured brother/tunnel colour.
        Color outlineColor = new Color(
            markerColor.getRed(),
            markerColor.getGreen(),
            markerColor.getBlue(),
            markerColor.getAlpha());
        graphics.setStroke(new BasicStroke(1.5f));

        boolean rendered = false;
        for (int x = minX; x <= maxX && !rendered; x++)
        {
            for (int y = minY; y <= maxY && !rendered; y++)
            {
                Tile tile = tiles[plane][x][y];
                if (tile == null || tile.getGameObjects() == null)
                {
                    continue;
                }

                for (GameObject object : tile.getGameObjects())
                {
                    if (object == null || !object.getSceneMinLocation().equals(tile.getSceneLocation()))
                    {
                        continue;
                    }

                    ObjectComposition composition = client.getObjectDefinition(object.getId());
                    String name = composition == null ? null : composition.getName();
                    if (name == null || !"Sarcophagus".equalsIgnoreCase(name))
                    {
                        continue;
                    }

                    Shape hull = object.getConvexHull();
                    if (hull != null)
                    {
                        OverlayUtil.renderPolygon(graphics, hull, outlineColor);

                        // Put the brother name on the sarcophagus itself, rather
                        // than on a nearby crypt floor tile.
                        String label = currentBrother.getDisplayName();
                        graphics.setFont(FontManager.getRunescapeBoldFont());
                        Point text = Perspective.getCanvasTextLocation(
                            client,
                            graphics,
                            object.getLocalLocation(),
                            label,
                            0);
                        if (text != null)
                        {
                            OverlayUtil.renderTextLocation(graphics, text, label, markerColor);
                        }

                        rendered = true;
                        break;
                    }
                }
            }
        }

        graphics.setStroke(oldStroke);
        graphics.setColor(oldColor);
        graphics.setFont(oldFont);
    }

    /**
     * Outline the staircase in the brother crypt the player is currently inside.
     * Nothing is drawn for the other five rooms. We identify the staircase from
     * its live object definition/action rather than relying on a brittle object ID.
     */
    private void renderCurrentRoomStaircase(Graphics2D graphics)
    {
        if (client.getLocalPlayer() == null)
        {
            return;
        }

        WorldView worldView = client.getLocalPlayer().getWorldView();
        int plane = worldView.getPlane();
        WorldPoint player = client.getLocalPlayer().getWorldLocation();
        BarrowsBrotherLocationData currentBrother = nearestCryptBrother(player, plane, 16);

        // No staircase marker before/during the fight.
        if (currentBrother == null || !plugin.isBrotherKilled(currentBrother))
        {
            return;
        }

        final int staircaseId = getCryptStaircaseObjectId(currentBrother);
        final Color configured = config.roomStaircaseColor();
        final Color green = new Color(0x00, 0xFF, 0x3C, configured.getAlpha());
        final Stroke oldStroke = graphics.getStroke();
        final Color oldColor = graphics.getColor();

        graphics.setStroke(new BasicStroke(
                Math.max(3, config.roomStaircaseWidth()),
                BasicStroke.CAP_ROUND,
                BasicStroke.JOIN_ROUND));

        Tile[][][] tiles = worldView.getScene().getTiles();

        // Find the exact staircase object for this brother and draw its MODEL
        // hull. We intentionally do not render a canvas tile or a nearby-object
        // fallback: the green marker must wrap the entire staircase itself.
        for (Tile[] row : tiles[plane])
        {
            if (row == null)
            {
                continue;
            }

            for (Tile tile : row)
            {
                if (tile == null)
                {
                    continue;
                }

                if (tile.getGameObjects() != null)
                {
                    for (GameObject object : tile.getGameObjects())
                    {
                        if (object == null || object.getId() != staircaseId)
                        {
                            continue;
                        }

                        Shape hull = object.getConvexHull();
                        if (hull != null)
                        {
                            OverlayUtil.renderPolygon(graphics, hull, green);
                            graphics.setStroke(oldStroke);
                            graphics.setColor(oldColor);
                            return;
                        }

                        // If RuneLite cannot expose a hull for this model, use
                        // the object's full clickable shape—not its ground tile.
                        Shape clickbox = object.getClickbox();
                        if (clickbox != null)
                        {
                            OverlayUtil.renderPolygon(graphics, clickbox, green);
                            graphics.setStroke(oldStroke);
                            graphics.setColor(oldColor);
                            return;
                        }
                    }
                }

                WallObject wall = tile.getWallObject();
                if (wall != null && wall.getId() == staircaseId)
                {
                    Shape hull = wall.getConvexHull();
                    if (hull == null)
                    {
                        hull = wall.getClickbox();
                    }
                    if (hull != null)
                    {
                        OverlayUtil.renderPolygon(graphics, hull, green);
                        graphics.setStroke(oldStroke);
                        graphics.setColor(oldColor);
                        return;
                    }
                }

                DecorativeObject decorative = tile.getDecorativeObject();
                if (decorative != null && decorative.getId() == staircaseId)
                {
                    Shape hull = decorative.getConvexHull();
                    if (hull == null)
                    {
                        hull = decorative.getClickbox();
                    }
                    if (hull != null)
                    {
                        OverlayUtil.renderPolygon(graphics, hull, green);
                        graphics.setStroke(oldStroke);
                        graphics.setColor(oldColor);
                        return;
                    }
                }

                GroundObject ground = tile.getGroundObject();
                if (ground != null && ground.getId() == staircaseId)
                {
                    Shape hull = ground.getConvexHull();
                    if (hull == null)
                    {
                        hull = ground.getClickbox();
                    }
                    if (hull != null)
                    {
                        OverlayUtil.renderPolygon(graphics, hull, green);
                        graphics.setStroke(oldStroke);
                        graphics.setColor(oldColor);
                        return;
                    }
                }
            }
        }

        graphics.setStroke(oldStroke);
        graphics.setColor(oldColor);
    }

    private static int getCryptStaircaseObjectId(BarrowsBrotherLocationData brother)
    {
        switch (brother)
        {
            case AHRIM:
                return 20667;
            case DHAROK:
                return 20668;
            case GUTHAN:
                return 20669;
            case KARIL:
                return 20670;
            case TORAG:
                return 20671;
            case VERAC:
                return 20672;
            default:
                return -1;
        }
    }

    private static WorldPoint getCryptStairPoint(BarrowsBrotherLocationData brother, int plane)
    {
        switch (brother)
        {
            case AHRIM:
                return new WorldPoint(3557, 9703, plane);
            case DHAROK:
                return new WorldPoint(3556, 9718, plane);
            case GUTHAN:
                return new WorldPoint(3534, 9704, plane);
            case KARIL:
                return new WorldPoint(3546, 9684, plane);
            case TORAG:
                return new WorldPoint(3568, 9683, plane);
            case VERAC:
                return new WorldPoint(3578, 9706, plane);
            default:
                throw new IllegalArgumentException("Unknown Barrows brother: " + brother);
        }
    }

    private BarrowsBrotherLocationData nearestCryptBrother(WorldPoint player, int plane, int maxDistance)
    {
        BarrowsBrotherLocationData nearest = null;
        int best = Integer.MAX_VALUE;
        for (BarrowsBrotherLocationData brother : BarrowsBrotherLocationData.values())
        {
            WorldPoint marker = WorldPoint.fromRegion(
                CRYPT_REGION_ID, brother.getCryptRegionX(), brother.getCryptRegionY(), plane);
            int distance = Math.abs(player.getX() - marker.getX()) + Math.abs(player.getY() - marker.getY());
            if (distance < best)
            {
                best = distance;
                nearest = brother;
            }
        }
        return best <= maxDistance ? nearest : null;
    }

}

package com.barrowswithbenefits;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

/**
 * Compact replacement for Jagex's Barrows HUD, styled like RuneLite's
 * official Barrows Brothers overlay. Hold Alt to drag it.
 */
final class BarrowsTrackerOverlay extends OverlayPanel
{
    private final BarrowsWithBenefitsPlugin plugin;
    private final BarrowsWithBenefitsConfig config;

    @Inject
    BarrowsTrackerOverlay(BarrowsWithBenefitsPlugin plugin, BarrowsWithBenefitsConfig config)
    {
        super(plugin);
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
        setPriority(PRIORITY_LOW);
        setMovable(true);
        setSnappable(true);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!plugin.isInBarrowsArea())
        {
            return null;
        }

        // Match RuneLite's standard Barrows overlay: one compact left/right row
        // per brother, using the normal OverlayPanel background and padding.
        for (BarrowsBrotherLocationData brother : plugin.getEffectiveBrotherOrder())
        {
            boolean tunnel = brother == plugin.getTunnelBrother();
            boolean killed = plugin.isBrotherKilled(brother);

            Color statusColor = tunnel
                    ? config.tunnelHighlightColor()
                    : (killed ? config.killedBrotherColor() : Color.WHITE);
            String status = tunnel ? "◆" : (killed ? "✓" : "✗");
            Color rightColor = tunnel
                    ? config.tunnelHighlightColor()
                    : (killed ? config.killedBrotherColor() : Color.RED);

            panelComponent.getChildren().add(LineComponent.builder()
                    .left(brother.getDisplayName())
                    .leftColor(statusColor)
                    .right(status)
                    .rightFont(FontManager.getDefaultFont())
                    .rightColor(rightColor)
                    .build());
        }

        // Tunnel kill plan is part of the same panel, directly below the brothers.
        if (plugin.isInTunnelMaze() && config.showTunnelKillTracker())
        {
            addTarget("Bloodworm", plugin.getBloodwormKills(), config.bloodwormTarget());
            addTarget("Crypt rat", plugin.getCryptRatKills(), config.cryptRatTarget());
            addTarget("Giant crypt rat", plugin.getGiantCryptRatKills(), config.giantCryptRatTarget());
            addTarget("Crypt spider", plugin.getCryptSpiderKills(), config.cryptSpiderTarget());
            addTarget("Giant crypt spider", plugin.getGiantCryptSpiderKills(), config.giantCryptSpiderTarget());
            addTarget("Skeleton", plugin.getSkeletonKills(), config.skeletonTarget());
        }

        if (plugin.isInTunnelMaze() && config.showRewardPotential())
        {
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Potential")
                    .leftColor(plugin.areTunnelKillTargetsComplete()
                            ? config.killedBrotherColor()
                            : Color.WHITE)
                    .right(String.format("%.1f%%", plugin.getRewardPotentialPercent()))
                    .rightColor(plugin.areTunnelKillTargetsComplete()
                            ? config.killedBrotherColor()
                            : Color.WHITE)
                    .build());
        }

        return super.render(graphics);
    }

    private void addTarget(String name, int current, int target)
    {
        if (target <= 0)
        {
            return;
        }

        boolean complete = current >= target;
        panelComponent.getChildren().add(LineComponent.builder()
                .left(name)
                .leftColor(complete ? config.killedBrotherColor() : Color.WHITE)
                .right(current + "/" + target + (complete ? " ✓" : ""))
                .rightColor(complete ? config.killedBrotherColor() : Color.WHITE)
                .build());
    }
}

package com.barrowswithbenefits;

